-- Пункты выдачи: реальные 20 точек со старого сайта (tirestock.ru/points/) вместо
-- демо-сида. Плюс поля под новые фичи:
--   slug — для отдельной страницы пункта (/points/<slug>), кликабельная карточка;
--   is_main — «основной адрес» (несколько, а не один центральный): показываются
--     крупными карточками с телефоном и первыми в списке/корзине;
--   city — задел под возврат Москвы (СПб+МСК): пункты фильтруются по городу.
ALTER TABLE pickup_points ADD COLUMN slug    TEXT NOT NULL DEFAULT '';
ALTER TABLE pickup_points ADD COLUMN is_main BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE pickup_points ADD COLUMN city    TEXT NOT NULL DEFAULT 'spb';

-- Сносим демо-сид (миграция 0013) — заменяем реальными данными.
DELETE FROM pickup_points;

-- Реальные пункты выдачи СПб (source: tirestock.ru/points/, 20 точек).
-- Основные (is_main) — Полюстровский, Торфяная дорога, Новоселов (по требованию владельца).

CREATE UNIQUE INDEX pickup_points_slug_key ON pickup_points (slug) WHERE slug <> '';
